"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[877],{2614:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"DocsSidebar":[{"type":"link","label":"Introduction","href":"/docs/getting-started/intro","docId":"getting-started/intro","unlisted":false},{"type":"category","label":"Concepts","items":[{"type":"link","label":"Device Binding","href":"/docs/concepts/device-binding","docId":"concepts/device-binding","unlisted":false},{"type":"link","label":"Account Screen","href":"/docs/concepts/devices-screen","docId":"concepts/devices-screen","unlisted":false},{"type":"link","label":"Spaces","href":"/docs/concepts/spaces","docId":"concepts/spaces","unlisted":false},{"type":"link","label":"Roles & Permissions","href":"/docs/concepts/roles-permissions","docId":"concepts/roles-permissions","unlisted":false},{"type":"link","label":"How Instant Connect Works","href":"/docs/concepts/dasset-instant-connect","docId":"concepts/dasset-instant-connect","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Features","items":[{"type":"link","label":"Account Settings","href":"/docs/features/account-settings","docId":"features/account-settings","unlisted":false},{"type":"link","label":"Contacts Back-Up","href":"/docs/features/contacts-backup","docId":"features/contacts-backup","unlisted":false},{"type":"link","label":"Recycle Bin","href":"/docs/features/recycle","docId":"features/recycle","unlisted":false},{"type":"link","label":"File De-Duplication","href":"/docs/features/de-duplication","docId":"features/de-duplication","unlisted":false},{"type":"link","label":"External Storage","href":"/docs/features/external-storage","docId":"features/external-storage","unlisted":false},{"type":"link","label":"LAN Access (Samba)","href":"/docs/features/samba","docId":"features/samba","unlisted":false},{"type":"link","label":"Streaming Media (DLNA)","href":"/docs/features/dlna","docId":"features/dlna","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"OEMs","items":[{"type":"link","label":"DASSET Software Platform","href":"/docs/oem-odm/oems","docId":"oem-odm/oems","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"FAQ","href":"/docs/faq/faqs","docId":"faq/faqs","unlisted":false},{"type":"category","label":"Troubleshooting","items":[{"type":"link","label":"Connectivity Errors","href":"/docs/troubleshooting/connectivity","docId":"troubleshooting/connectivity","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"Privacy Policy","href":"/docs/privacy-policy/","docId":"privacy-policy/privacy-policy","unlisted":false}]},"docs":{"concepts/dasset-instant-connect":{"id":"concepts/dasset-instant-connect","title":"How Instant Connect Works","description":"Instant Connect provides the ability to reliably connect to a DASSET Data Hub from the DASSET client applications on your phone, PC or Mac.  If Instant Connect is unable to connect to the destination Data Hub after completing the Instant Connect connectivity procedure, Instant Connect will route the connection through PlanetX Labs Cloud Relay Services to establish alternative connectivity.  The following explains the process by which Instant Connect performs for connectivity.","sidebar":"DocsSidebar"},"concepts/device-binding":{"id":"concepts/device-binding","title":"Device Binding","description":"New DASSET Data Hubs are shipped ready to be setup by the owner of the device. The owner has complete administrative control over how the device is used, including who else may or may not be able to access content on the Data Hub.  Owners of a Data Hub are bound to the device through a process called binding. Only one user account can be bound as the Owner of a Data Hub.","sidebar":"DocsSidebar"},"concepts/devices-screen":{"id":"concepts/devices-screen","title":"Account Screen","description":"After logging-in to your DASSET user account, you are presented with the Account Screen, where you manage all aspects of your DASSET user account, such as connecting to devices and changing your account information.","sidebar":"DocsSidebar"},"concepts/roles-permissions":{"id":"concepts/roles-permissions","title":"Roles & Permissions","description":"DASSET uses Role-Based Access Control (RBAC) to control what permissions users of the Data Hub can, or cannot, do.  Each user of the system is assigned a role, either automatically by the system, or specifically by the Owner of the device.","sidebar":"DocsSidebar"},"concepts/spaces":{"id":"concepts/spaces","title":"Spaces","description":"The exposure of the file system in DASSET is designed to present data to the user that only they have access to.  Rather than combing through a tree of file folders containing both user and system files, DASSET easily organizes user\'s data into Spaces.  Spaces are logical representations of data on the Data Hub.","sidebar":"DocsSidebar"},"faq/faqs":{"id":"faq/faqs","title":"FAQs","description":"What exactly is a DASSET Data Hub?","sidebar":"DocsSidebar"},"features/account-settings":{"id":"features/account-settings","title":"Account Settings","description":"Your DASSET User Account can be used on several DASSET Data Hubs, rather than having to create new accounts for each Data Hub you have been invited to join.  If you only have 1 Data Hub, then the relationship between Account and Data Hub is 13.","sidebar":"DocsSidebar"},"features/contacts-backup":{"id":"features/contacts-backup","title":"Contacts Back-Up","description":"In addition to data we think of as files and photos, DASSET also offers the ability to back-up other types of data that is important to you - like your contacts on your phone.  Contacts Backup provides a simple way to back-up, and restore, your contacts.","sidebar":"DocsSidebar"},"features/de-duplication":{"id":"features/de-duplication","title":"File De-Duplication","description":"When bringing all of your data together from muptile devices and clouds, it\'s likely that you will have the same file from these locations, copied multiple times to your Data Hub.  Finding these files on your own, and deciding which ones to keep vs. delete can be daunting.","sidebar":"DocsSidebar"},"features/dlna":{"id":"features/dlna","title":"Streaming Media (DLNA)","description":"Your DASSET Data Hub can act as a media server for your home or office, giving you the ability to stream content such as videos and audio to TVs, consoles and stereos that support the DLNA protocol.","sidebar":"DocsSidebar"},"features/external-storage":{"id":"features/external-storage","title":"External Storage","description":"Your DASSET Data Hub has the ability to view and manage data that reside on storage devices that can connect to your Data Hub via USB.  These include portable HDDs, SSDs and thumbdrives.  Rather than copying the contents of these storage devices to your computer first, and then transferring them to your Data Hub, you can simply copy them directly using External Storage.","sidebar":"DocsSidebar"},"features/recycle":{"id":"features/recycle","title":"Recycle Bin","description":"Like most operating systems, DASSET comes with the ability to restore files accidentally deleted by the user.  The Recycle Bin is where all files deleted on the system are placed, giving you the ability to undo those \\"Oops\\" moments of deleting a file inadvertantly.","sidebar":"DocsSidebar"},"features/samba":{"id":"features/samba","title":"LAN Access (Samba)","description":"In addition to accessing files on your Data Hub through the DASSET application, the ability to do so directly from a device that supports the SMB networking protocol), such as Windows and Linux/Unix-based Operating Systems like Android and Apple MacOS and iOS.  Samba in DASSET is an implementation of the SMB networking protocol, making it easy to establish file-sharing between your Windows, MacOS or mobile phone and a DASSET Data Hub.","sidebar":"DocsSidebar"},"getting-started/intro":{"id":"getting-started/intro","title":"Introduction COPY","description":"Our data dilemma","sidebar":"DocsSidebar"},"oem-odm/oems":{"id":"oem-odm/oems","title":"DASSET Software Platform","description":"The DASSET Software Platform is a suite of components and services that enables OEMs to build DASSET-Powered Data Hubs.  The following are the core components that make-up the software platform:","sidebar":"DocsSidebar"},"privacy-policy/privacy-policy":{"id":"privacy-policy/privacy-policy","title":"Privacy Policy","description":"Update Date: February 26, 2024","sidebar":"DocsSidebar"},"troubleshooting/connectivity":{"id":"troubleshooting/connectivity","title":"Connectivity Errors","description":"","sidebar":"DocsSidebar"}}}}')}}]);